  if (ctl.dk) {
    const v = ctl.dk[ctl.dk.length - 1];
    if (v) out.kel = { mid: v.mid, up: v.up, lo: v.lo, pos: price > v.up ? "상단 위(돌파)" : price > v.mid ? "중심선~상단" : price > v.lo ? "하단~중심선" : "하단 아래" };
  }
